CREATE TABLE schema_version (version INTEGER PRIMARY KEY);
INSERT INTO schema_version VALUES (1);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE sessions (id INTEGER PRIMARY KEY, start_ts INTEGER NOT NULL, end_ts INTEGER, stats TEXT NOT NULL);
CREATE INDEX idx_sessions_start ON sessions(start_ts);
CREATE TABLE session_days (id INTEGER NOT NULL, date TEXT NOT NULL, start_ts INTEGER NOT NULL, end_ts INTEGER NOT NULL, stats TEXT NOT NULL, PRIMARY KEY(id,date));
CREATE TABLE minute_stats (minute_ts INTEGER PRIMARY KEY, date TEXT NOT NULL, stats TEXT NOT NULL);
CREATE INDEX idx_minutes_date ON minute_stats(date);
CREATE TABLE hourly_stats (hour_start INTEGER NOT NULL, date TEXT NOT NULL, stats TEXT NOT NULL, PRIMARY KEY(hour_start,date));
CREATE INDEX idx_hours_date ON hourly_stats(date);
CREATE TABLE daily_stats (date TEXT PRIMARY KEY, stats TEXT NOT NULL);
CREATE TABLE monitors (monitor_id INTEGER PRIMARY KEY, device_name TEXT NOT NULL, width INTEGER, height INTEGER, dpi_x REAL, dpi_y REAL, first_seen INTEGER, last_seen INTEGER, metadata TEXT NOT NULL);
CREATE TABLE heatmap_hourly (hour_start INTEGER NOT NULL, date TEXT NOT NULL, monitor_id INTEGER NOT NULL, grid_x INTEGER NOT NULL CHECK(grid_x BETWEEN 0 AND 63), grid_y INTEGER NOT NULL CHECK(grid_y BETWEEN 0 AND 35), dwell_count INTEGER DEFAULT 0, click_count INTEGER DEFAULT 0, left_clicks INTEGER DEFAULT 0, right_clicks INTEGER DEFAULT 0, middle_clicks INTEGER DEFAULT 0, scroll_count INTEGER DEFAULT 0, drag_count INTEGER DEFAULT 0, PRIMARY KEY(hour_start,date,monitor_id,grid_x,grid_y));
CREATE INDEX idx_heat_date ON heatmap_hourly(date);
CREATE TABLE raw_events (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, event_type TEXT NOT NULL, x_norm REAL, y_norm REAL, monitor_id INTEGER);
CREATE INDEX idx_events_ts ON raw_events(ts);


